select.where:

    and c.customer_code like concat('%', #{customerCode}, '%')


    and c.customer_name like concat('%', #{customerName}, '%')


    and c.contact_person like concat('%', #{contactPerson}, '%')


    and c.contact_phone = #{contactPhone}


    and c.contact_email = #{contactEmail}


    and c.payment_method = #{paymentMethod}


    and c.customer_level = #{customerLevel}


    and c.status = #{status}


    and c.del_flag = #{delFlag}

${params.dataScope}

mapper.update:
update md_customer
customer_code = #{customerCode}, customer_name = #{customerName}, contact_person = #{contactPerson}, contact_phone = #{contactPhone}, contact_email = #{contactEmail}, address = #{address}, credit_limit = #{creditLimit}, payment_method = #{paymentMethod}, customer_level = #{customerLevel}, status = #{status}, del_flag = #{delFlag}, update_by = #{updateBy}, update_time = sysdate(), remark = #{remark},
where customer_id = #{customerId}
